/* Question bank. Each question: id, t (topic), l (lesson), q, o (options), a (index of correct option), e (explanation).
 * Lesson check quizzes are built from every question tagged with that lesson. Exams sample by topic. */
(function () {
  const Q = [];
  const add = (id, t, l, q, o, a, e) => Q.push({ id, t, l, q, o, a, e });

  /* ===================== Stage 1 — foundations */
  add('fc1', 'foundations', 'f-commodity', 'Which product is the best example of a commodity?', ['A branded smartphone', 'Hot-rolled coil to a stated grade and thickness', 'A custom-designed bridge', 'A luxury watch'], 1, 'Commodities are standardised goods where one unit of the same specification can replace another. HRC to a stated grade is traded on specifications; branded or custom goods are differentiated.');
  add('fc2', 'foundations', 'f-commodity', 'A pension fund buys shares of a gold ETF. What kind of exposure does it have?', ['Physical ownership of specific bars', 'Financial exposure to the gold price', 'A forward purchase from a refiner', 'No gold-price exposure'], 1, 'An ETF share gives price exposure through a security. The fund owns shares, not specific bars, and never handles logistics.');
  add('fc3', 'foundations', 'f-commodity', 'Why is steel described as "less fungible" than gold?', ['Steel is cheaper', 'Steel products differ by grade, dimensions, standards and coatings, so one tonne cannot always replace another', 'Steel is not traded internationally', 'Steel has no exchange-traded contracts anywhere'], 1, 'A tonne of 12 mm B500B rebar cannot replace a tonne of 2 mm galvanised coil. Gold of the same fineness is nearly perfectly interchangeable.');
  add('fp1', 'foundations', 'f-participants', 'A merchant trading company typically earns its margin mainly from…', ['Owning mines', 'Arbitrage across location, time, quality and form, plus logistics and risk management', 'Exchange membership fees', 'Retail sales to consumers'], 1, 'Traders transform commodities in space (location), time (storage), and form/quality (blending, processing) and earn margins for logistics, financing and risk management.');
  add('fp2', 'foundations', 'f-participants', 'Which participant usually takes the highest physical-quality risk in a wheat chain?', ['A futures speculator', 'The flour mill that must produce consistent flour from the wheat it buys', 'A bank providing an LC', 'A shipping broker'], 1, 'The mill is the end user: if protein or falling number is off spec, its flour fails. That is why mills specify quality tightly and inspect.');
  add('fp3', 'foundations', 'f-participants', 'What does a broker do that a principal trader does not?', ['Takes title to the goods', 'Arranges trades between parties for a commission without taking the position', 'Guarantees payment', 'Insures the cargo'], 1, 'A broker intermediates; a principal buys and sells on its own account and carries the price, credit and performance risk.');
  add('fi1', 'foundations', 'f-instruments', 'What is the key difference between a forward and a futures contract?', ['Only forwards can be physically delivered', 'Futures are standardised, exchange-traded and cleared with daily margin; forwards are bilateral OTC contracts', 'Forwards are always cash settled', 'Futures have no expiry date'], 1, 'Both are commitments to trade later. Futures standardise terms and remove bilateral counterparty risk via the clearing house and margin; forwards are customised and bilateral.');
  add('fi2', 'foundations', 'f-instruments', 'A buyer pays a premium for the right but not the obligation to buy wheat futures at 600 c/bu. What did they buy?', ['A put option', 'A call option', 'A swap', 'A forward'], 1, 'The right to buy is a call. The premium is the maximum loss for the buyer.');
  add('fi3', 'foundations', 'f-instruments', 'A steel distributor wants to fix its average purchase price over the next 6 months without physical delivery. Which instrument fits best?', ['A fixed-for-floating swap settled in cash', 'Buying a cargo spot today', 'A call option on gold', 'A documentary collection'], 0, 'A swap fixes the price on a notional quantity: the distributor pays fixed and receives the floating average, settled in cash, while buying physical steel as normal.');
  add('fi4', 'foundations', 'f-instruments', 'Which statement about cash-settled contracts is correct?', ['They require a warehouse receipt', 'At expiry, only the money difference versus a reference price is paid', 'They cannot be used to hedge', 'They always settle at the contract price'], 1, 'Cash settlement exchanges money against a final settlement price — no goods move. It can hedge as long as the reference price is correlated with the exposure.');
  add('fpr1', 'foundations', 'f-pricing', 'The bid is 1,998.50 and the ask is 1,999.30. If you buy at the ask and immediately sell at the bid, what do you lose per unit?', ['0.40', '0.80', '1.60', 'Nothing'], 1, 'Round-trip cost = ask − bid = 0.80 per unit (before fees). Spread is a real trading cost.');
  add('fpr2', 'foundations', 'f-pricing', 'Inventories are very low and a supply disruption hits. What is the most likely price reaction compared with a market with large stocks?', ['Smaller, because traders are calmer', 'Larger, because there is little buffer to absorb the shortfall', 'No difference', 'Prices always fall in disruptions'], 1, 'Low stocks remove the buffer. Buyers must bid up to ration demand, so prices are more volatile.');
  add('fpr3', 'foundations', 'f-pricing', 'Over the long run, what tends to anchor prices of a produced commodity?', ['The most recent news headline', 'The cost of the marginal producer needed to meet demand', 'The bid-ask spread', 'The exchange\'s opening hours'], 1, 'If prices fall below the cost of the marginal producer, supply shrinks; if far above, new supply arrives. The cost curve shapes long-run price ranges (not short-run moves).');
  add('fpr4', 'foundations', 'f-pricing', 'A market is described as "illiquid". What should a trader expect?', ['Tight spreads and deep order books', 'Wider spreads and larger price impact when trading size', 'Guaranteed profits', 'No volatility'], 1, 'In illiquid markets fewer participants and smaller order books mean wider spreads and bigger moves when you trade.');
  add('fe1', 'foundations', 'f-economics', 'A trader buys 10,000 t at 250/t and sells at 280/t. Logistics cost 22/t and financing 3/t. Net profit?', ['300,000', '80,000', '50,000', '30,000'], 2, '(280 − 250 − 22 − 3) × 10,000 = 5 × 10,000 = 50,000. The "30/t margin" headline disappears quickly once costs are counted.');
  add('fe2', 'foundations', 'f-economics', 'Two deals each make 100,000 profit. Deal A ties up 2,000,000 for 30 days, deal B ties up 2,000,000 for 120 days. Which is better on capital efficiency?', ['B', 'A', 'They are equal', 'Cannot compare profits'], 1, 'Same profit with capital tied up a quarter of the time: A\'s annualised return is about 4× B\'s. Always look at return on capital and duration, not profit alone.');
  add('fe3', 'foundations', 'f-economics', 'What is working capital in a trading deal?', ['The trader\'s office equipment', 'Cash tied up between paying for goods and costs and collecting from the buyer', 'The total contract value', 'Gross margin'], 1, 'Working capital is the money locked in inventory and receivables. It needs funding (equity or bank lines) and costs interest.');
  add('fe4', 'foundations', 'f-economics', 'Why does cargo insurance matter even if the deal is CFR to the buyer?', ['It never matters under CFR', 'Under CFR risk passes at loading, so the buyer bears transit risk and normally insures; the seller may still need cover until loading', 'CFR requires the seller to insure 110%', 'Insurance replaces the bill of lading'], 1, 'CFR: seller pays freight but risk transfers when goods are on board. The buyer should arrange marine cover for the voyage; the seller protects its pre-loading risk.');
  add('fr1', 'risk', 'f-risk', 'A buyer accepts your cargo, then goes bankrupt before paying. Which risk materialised?', ['Market risk', 'Credit risk', 'Basis risk', 'Freight risk'], 1, 'Failure to pay amounts owed is credit risk (a form of counterparty risk).');
  add('fr2', 'risk', 'f-risk', 'A clerk types the wrong vessel name on the bill of lading and the LC payment is refused. Which risk is this?', ['Operational/documentation risk', 'Market risk', 'Currency risk', 'Concentration risk'], 0, 'Process and human error causing loss is operational risk; in trade finance it shows up as documentary discrepancies.');
  add('fr3', 'risk', 'f-risk', 'You own 20,000 t of unsold sugar in a warehouse with no hedge. Which risk is largest day-to-day?', ['Market (price) risk', 'Despatch risk', 'Sanctions risk only', 'None — inventory is an asset'], 0, 'Unhedged inventory is a long price position: every move in sugar prices changes its value.');
  add('fa1', 'accounting', 'f-accounting', 'A trader sells a cargo at a profit on 90-day credit terms after paying the supplier in advance. Where does the unpaid sale appear?', ['As cash', 'As accounts receivable on the balance sheet', 'As accounts payable', 'It does not appear until paid'], 1, 'Under accrual accounting revenue is recognised on delivery and the unpaid amount is a receivable (an asset), not cash.');
  add('fa2', 'accounting', 'f-accounting', 'How can a profitable trading company run out of cash?', ['It cannot — profit equals cash', 'Profit is recognised on delivery while cash goes out to suppliers earlier and comes in from buyers later; rapid growth or late payers drain cash', 'Only through fraud', 'Only if gross margin is negative'], 1, 'Profit ≠ cash. Paying suppliers before collecting from buyers creates a funding gap; growth multiplies it. This is why traders watch working capital and liquidity, not just P&L.');
  add('fa3', 'accounting', 'f-accounting', 'Which statement shows whether the company generated or consumed cash from trading operations?', ['Balance sheet', 'Cash flow statement (operating section)', 'Trading P&L', 'Inventory report'], 1, 'Operating cash flow = profit adjusted for non-cash items and working-capital changes (inventory, receivables, payables).');
  add('fa4', 'accounting', 'f-accounting', 'Inventory rose from 5m to 12m and receivables from 3m to 7m in a year, payables unchanged. Profit was 2m. Approximate operating cash flow?', ['+2m', '−9m', '+13m', '−2m'], 1, 'Operating cash ≈ profit − increase in inventory − increase in receivables + increase in payables = 2 − 7 − 4 + 0 = −9m. Profitable but cash-negative.');
  add('fa5', 'accounting', 'f-accounting', 'A trader marks its unhedged wheat inventory to market and books a large unrealised gain. What is true?', ['The cash is in the bank', 'The gain is on paper until the wheat is sold and paid for; prices can reverse', 'Unrealised gains are taxed and paid immediately everywhere', 'It reduces working capital'], 1, 'Unrealised gains reflect current valuation, not cash received. Sound risk management treats them cautiously.');

  /* ===================== Stage 2 — markets */
  add('mv1', 'markets', 'm-valuechain', 'Put the steps in the right order: (1) trading (2) production (3) final consumption (4) processing.', ['2-4-1-3', '1-2-3-4', '4-2-1-3', '2-1-4-3'], 0, 'Typical chain: production → collection → processing → storage → transport → trading/financing → delivery → final consumption. (Trading can happen at several stages, but processing precedes final use.)');
  add('mv2', 'markets', 'm-valuechain', 'Where along the wheat chain is quality usually measured and graded first?', ['At the consumer bakery', 'When grain is received at the country or port elevator', 'Only on the futures exchange', 'At the bank'], 1, 'Elevators sample and grade on receipt (moisture, protein, test weight, foreign material) and segregate stocks by quality.');
  add('mf1', 'markets', 'm-flows', 'Why do wheat import origins often shift during the year?', ['Ports close on weekends', 'Harvests in different hemispheres arrive at different times, changing which origin is cheapest', 'Wheat prices are fixed by governments', 'Ships cannot cross the equator'], 1, 'Northern hemisphere harvests mostly come in mid-year, southern ones (e.g. Australia, Argentina) around the turn of the year. Fresh supply makes an origin competitive.');
  add('mf2', 'markets', 'm-flows', 'A weather problem hits during which period would most affect sugar supply from a cane producer?', ['Any time — no seasonality', 'During the growing period and harvest/crushing season', 'Only during shipment', 'Only after refining'], 1, 'Drought during cane growth cuts yields; rain during harvest interrupts crushing. Both matter for that season\'s output.');
  add('mm1', 'markets', 'm-macro', 'Commodities priced in USD typically become more expensive for a buyer in Egypt when…', ['The Egyptian pound strengthens against the USD', 'The Egyptian pound weakens against the USD', 'US interest rates fall', 'Freight rates fall'], 1, 'A weaker local currency means more pounds per dollar, so a USD price costs more in local terms, even if the USD price is unchanged.');
  add('mm2', 'markets', 'm-macro', 'Higher interest rates affect physical traders mainly by…', ['Reducing freight', 'Raising the cost of financing inventory and receivables, and the cost of carry', 'Increasing commodity quality', 'Removing currency risk'], 1, 'Traders borrow to fund stock and receivables. Higher rates raise carrying costs and can push forward curves toward contango.');
  add('mm3', 'markets', 'm-macro', 'A new buyer is owned through shell companies by a person on a sanctions list. What should a compliant trader do?', ['Trade but charge a higher price', 'Not trade; screening and beneficial ownership checks exist to prevent this', 'Trade via a broker so it is not your problem', 'Ask the buyer to pay in cash'], 1, 'Sanctions apply to owned/controlled entities. Routing via intermediaries does not remove liability. Stop and escalate to compliance.');
  add('ml1', 'markets', 'm-logistics-prices', 'Wheat is 230/t FOB at origin A and 262/t delivered at port B. Freight A→B is 38/t. What does this suggest?', ['A profitable arbitrage of 32/t', 'No arbitrage: delivered cost (268) is above the destination price', 'Destination is cheaper than origin', 'Freight is irrelevant'], 1, '230 + 38 = 268 > 262 before insurance, financing and handling. The apparent 32/t gap is more than eaten by freight.');
  add('ml2', 'markets', 'm-logistics-prices', 'Why can the same commodity have different prices in two regions at the same time?', ['Price differences always mean a market error', 'Freight, duties, quality, timing, currency and local supply-demand create persistent differentials', 'Exchanges set regional prices', 'Only due to fraud'], 1, 'Regional differences reflect costs of moving goods and local fundamentals. Arbitrage keeps them within a band set by transfer costs.');
  add('ms1', 'markets', 'm-shocks', 'Which is more likely a STRUCTURAL change rather than a temporary move?', ['A one-week port strike', 'A sustained shift in a major country\'s policy that permanently removes export capacity, or a large new production capacity coming online over years', 'A single bad weather day', 'A rumour later denied'], 1, 'Structural changes alter the medium-term balance (capacity, technology, policy, demand trends). Temporary moves fade as the disruption resolves.');
  add('ms2', 'markets', 'm-shocks', 'High prices persist for two years after a drought even though the next crop recovered. What could explain it?', ['Nothing — prices must revert', 'Inventories were depleted and need rebuilding; or demand/supply changed structurally', 'Exchange error', 'Freight rates fell'], 1, 'Restocking demand can keep prices high after the shock, and the shock may have revealed structural issues. Check the balance sheet: stocks-to-use tells you how tight things still are.');
  add('ms3', 'markets', 'm-shocks', 'When corn becomes much cheaper than feed wheat, what typically happens?', ['Feed users substitute corn for wheat, reducing feed-wheat demand', 'Wheat demand rises', 'Nothing — no substitution exists', 'Mills switch to corn for bread flour'], 0, 'In animal feed, energy grains are partially substitutable. Price relationships drive substitution at the margin; bread flour cannot simply switch.');

  /* ===================== Stage 3 — gold */
  add('gb1', 'gold', 'g-basics', 'How many grams in one troy ounce?', ['28.35 g', '31.1035 g', '30 g', '32.15 g'], 1, 'Troy ounce = 31.1034768 g. 28.35 g is the ordinary (avoirdupois) ounce — mixing them causes ~9.7% valuation errors.');
  add('gb2', 'gold', 'g-basics', 'An 18-karat jewellery item weighs 50 g. How much fine gold does it contain?', ['50 g', '37.5 g', '18 g', '45 g'], 1, '18/24 = 75% fine. 50 × 0.75 = 37.5 g fine gold.');
  add('gb3', 'gold', 'g-basics', 'What is a typical minimum fineness for a large LBMA Good Delivery gold bar?', ['916.7', '995.0', '750.0', '999.99 only'], 1, 'The LBMA Good Delivery standard for large gold bars requires at least 995.0 fineness (plus weight range and accredited refiner).');
  add('gb4', 'gold', 'g-basics', 'Which is NOT a major category of gold demand?', ['Jewellery', 'Central bank purchases', 'Investment (bars, coins, ETFs)', 'Fuel for power generation'], 3, 'Gold demand is jewellery, technology/industry, investment and central banks. It is not a fuel.');
  add('gi1', 'gold', 'g-instruments', 'An investor holds unallocated gold with a bullion bank that fails. What is their position?', ['They own specific bars and collect them', 'They are typically an unsecured creditor of the bank', 'The exchange guarantees them', 'They lose nothing by law'], 1, 'Unallocated gold is a claim on the institution, not title to specific bars. Allocated gold, properly documented, belongs to the client.');
  add('gi2', 'gold', 'g-instruments', 'Which gold instrument requires daily margin and has a fixed expiry?', ['Allocated bullion', 'Gold ETF share', 'Gold futures', 'Gold coins'], 2, 'Futures are marked to market daily with margin, and each contract month expires.');
  add('gi3', 'gold', 'g-instruments', 'A jeweller wants protection against a price rise for metal it will buy in 3 months, but keep the benefit if prices fall. Best fit?', ['Sell futures', 'Buy a call option', 'Sell a call option', 'Buy allocated gold today with no financing'], 1, 'A long call caps the purchase price while keeping downside benefit, for the premium. Selling futures would add exposure in the wrong direction.');
  add('gd1', 'gold', 'g-drivers', 'Other things equal, rising real interest rates tend to…', ['Increase gold\'s appeal because it pays interest', 'Raise the opportunity cost of holding gold, a headwind for price', 'Have no relationship with gold', 'Increase jewellery demand automatically'], 1, 'Gold yields nothing; higher real yields on bonds make holding gold relatively costlier. The relationship is a tendency and has broken down at times.');
  add('gd2', 'gold', 'g-drivers', 'Why might gold fall during an acute financial crisis?', ['Gold is never a safe haven', 'Investors sell liquid assets, including gold, to raise cash for margin calls; a rising USD can also weigh', 'Gold mines close', 'Central banks ban gold'], 1, 'In "dash for cash" phases (e.g. autumn 2008, March 2020) gold fell alongside other assets before recovering. Liquidity needs dominate.');
  add('gd3', 'gold', 'g-drivers', 'Gold futures trade above spot by roughly the interest cost minus the lease rate. This shape is…', ['Backwardation', 'Contango (normal carry)', 'Inverted premium', 'A discrepancy'], 1, 'Gold\'s forward curve normally reflects cost of carry: contango. Backwardation in gold would signal unusual physical tightness.');
  add('gd4', 'gold', 'g-drivers', 'Local gold in a country trades at a discount to the international benchmark. A possible reason?', ['Strong local demand', 'Weak local demand, import duty changes or restrictions affecting local supply/demand balance', 'The benchmark is wrong', 'Discounts are impossible'], 1, 'Local premiums/discounts reflect local supply-demand, duties, taxes, currency controls and logistics. Weak demand or excess local supply can produce discounts.');

  /* ===================== wheat */
  add('wb1', 'wheat', 'w-basics', 'Why is protein content important in milling wheat?', ['It sets the ship size', 'It strongly influences gluten and baking quality, so mills pay premiums for higher protein', 'It determines the bushel weight', 'Protein has no commercial relevance'], 1, 'Bread flours need higher protein; protein premiums/discounts are central to wheat pricing.');
  add('wb2', 'wheat', 'w-basics', '1,000 t of wheat at 15% moisture is dried to 13%. Approximately how much weight remains?', ['1,000 t', 'about 977 t', '870 t', '980 t exactly by subtracting 2%'], 1, 'Shrink = (15 − 13) / (100 − 13) = 2.30%. Remaining ≈ 977 t. Subtracting a flat 2% understates the loss.');
  add('wb3', 'wheat', 'w-basics', 'A falling number test result is very low. What does it indicate?', ['Excellent baking quality', 'Sprout damage (high enzyme activity) that can make the wheat unsuitable for bread', 'Low moisture', 'High test weight'], 1, 'Low falling number = sprouting damage, often from rain at harvest; bakers reject it for bread flour.');
  add('wb4', 'wheat', 'w-basics', 'Why is storage management critical for grain?', ['Grain never deteriorates', 'Moisture, temperature and insects can spoil grain; poor storage destroys value and creates claims', 'Storage is free', 'Only gold needs storage'], 1, 'Grain is perishable relative to metals: aeration, drying, fumigation and stock rotation protect quality.');
  add('wm1', 'wheat', 'w-markets', 'Beginning stocks 30, production 120, imports 15, consumption 118, exports 17. Ending stocks?', ['30', '20', '50', '15'], 0, '30 + 120 + 15 − 118 − 17 = 30.');
  add('wm2', 'wheat', 'w-markets', 'Global stocks-to-use falls sharply. What is the typical market implication?', ['Lower prices', 'A tighter market, generally supportive of prices and higher volatility', 'No implication', 'Freight must fall'], 1, 'Lower stocks relative to use means less buffer. The relationship is not mechanical — where stocks sit (e.g. government reserves not available for export) matters.');
  add('wm3', 'wheat', 'w-markets', 'A major exporter announces an export ban. Which buyers are hurt most?', ['Exporters in other countries', 'Importers dependent on that origin who must find alternatives, often at higher prices', 'Domestic consumers in the banning country', 'Futures exchanges'], 1, 'Importers reliant on that origin scramble for supply; competing origins benefit. Domestic prices in the banning country often fall relative to world prices.');
  add('wm4', 'wheat', 'w-markets', 'Why should a trader not treat a single USDA report as a price forecast?', ['USDA reports are secret', 'Reports are estimates revised over time, markets anticipate them, and prices also depend on other factors', 'The reports only cover gold', 'They are always wrong'], 1, 'Balance sheets are revised; the market reacts to surprises versus expectations, not the level itself.');

  /* ===================== sugar */
  add('sb1', 'sugar', 's-basics', 'What is the main difference between raw and refined sugar for trading?', ['Raw sugar is sold to consumers', 'Raw sugar is an intermediate product (around 96–99° pol) shipped mainly in bulk to refineries; refined (white) sugar is high-purity for direct use', 'They are the same product', 'Refined sugar is only made from beet'], 1, 'Raw sugar needs further refining; whites are food-grade. Each has its own benchmark and logistics.');
  add('sb2', 'sugar', 's-basics', 'A cane mill in a flex-fuel country can switch output toward ethanol. When is it more likely to do so?', ['When sugar pays less than ethanol after costs', 'When sugar prices are much higher than ethanol parity', 'Never', 'Only in winter'], 0, 'Flexible mills maximise revenue: if ethanol pays better, they divert cane to ethanol, reducing sugar supply.');
  add('sb3', 'sugar', 's-basics', 'Raw sugar polarisation of 98.5° vs a 96° contract base means…', ['A discount', 'A premium under a typical polarisation scale', 'Rejection of the cargo', 'No effect on price'], 1, 'Higher sucrose content above the base earns a premium per contract scale; below base gets discounts (and may be rejected below a minimum).');
  add('sm1', 'sugar', 's-markets', 'Raw sugar at 20 c/lb equals approximately how much per metric ton?', ['USD 200', 'USD 441', 'USD 2,000', 'USD 92'], 1, '20 × 22.0462 = 440.9 USD/t. (1 t = 2,204.62 lb; 1 c/lb = USD 22.0462/t.)');
  add('sm2', 'sugar', 's-markets', 'Higher crude oil prices can support sugar prices mainly because…', ['Sugar is made from oil', 'Higher energy prices raise ethanol\'s attractiveness, pulling cane away from sugar in flex markets, and raise production costs', 'Oil and sugar are the same contract', 'Ships stop sailing'], 1, 'The energy link runs through ethanol economics and input/transport costs. It is a tendency, not a fixed ratio.');
  add('sm3', 'sugar', 's-markets', 'The white premium widens strongly. Who benefits most directly?', ['Raw sugar exporters only', 'Refiners that buy raw and sell white sugar', 'Cane farmers', 'Ethanol plants'], 1, 'The white premium approximates the refining margin before costs.');
  add('sm4', 'sugar', 's-markets', 'A weaker Brazilian real tends to…', ['Reduce Brazilian exports', 'Make exports more attractive in local-currency terms, potentially increasing supply and weighing on USD prices', 'Have no effect', 'Increase ethanol imports'], 1, 'Producers paid in USD earn more reais when the BRL weakens, encouraging sales/exports. The effect is a tendency and interacts with ethanol and other factors.');

  /* ===================== steel */
  add('stb1', 'steel', 'st-basics', 'Which steelmaking route mostly uses scrap as feed?', ['Blast furnace - basic oxygen furnace', 'Electric arc furnace', 'Coke oven', 'Sinter plant'], 1, 'EAFs melt scrap (and DRI/HBI) with electricity. BF-BOF reduces iron ore with coke.');
  add('stb2', 'steel', 'st-basics', 'Which semi-finished product is rolled into rebar and wire rod?', ['Slab', 'Billet', 'Coil', 'Plate'], 1, 'Billets (smaller square sections) feed long-product mills. Slabs feed flat mills.');
  add('stb3', 'steel', 'st-basics', 'Why can\'t a buyer of cold-rolled coil accept hot-rolled coil instead at a discount?', ['It is the same product', 'CRC has thinner gauges, tighter tolerances and better surface needed for its end use; HRC cannot meet that specification', 'HRC is illegal to import', 'HRC is always more expensive'], 1, 'Steel products serve different end uses. Specification, not just price, determines suitability.');
  add('sts1', 'steel', 'st-specs', 'What does a mill test certificate (MTC) typically report?', ['The vessel\'s itinerary', 'Chemical composition and mechanical properties of the heat/lot, traceable by heat number', 'The LC amount', 'Freight cost'], 1, 'MTCs link material to its heat and report chemistry (C, Mn, S, P…) and mechanical tests (yield, tensile, elongation).');
  add('sts2', 'steel', 'st-specs', 'Theoretical weight of 12 m of 16 mm rebar (≈ d²/162.2 kg/m)?', ['18.9 kg', '1.58 kg', '189 kg', '7.9 kg'], 0, '16² / 162.2 = 1.578 kg/m × 12 m = 18.94 kg.');
  add('sts3', 'steel', 'st-specs', 'A purchase spec says "HRC, S235JR, 3 mm" only. What critical item is missing?', ['Nothing', 'Width, coil weight, thickness and width tolerances, edge condition, standard edition, certificate type and packaging', 'The colour of the coil', 'The port captain\'s name'], 1, 'Vague specs create disputes. Professional specs state standard, grade, dimensions, tolerances, surface/edge, coil ID/OD/weight, certification and marking.');
  add('stm1', 'steel', 'st-markets', 'Iron ore prices rise 20%. What happens to steel prices?', ['They must rise 20% the next day', 'Mill costs rise, but the effect on steel prices depends on demand, capacity utilisation, competition and timing — not immediate or proportional', 'They fall', 'Nothing ever'], 1, 'Raw-material pass-through is partial and lagged. Weak demand can compress margins rather than lift prices.');
  add('stm2', 'steel', 'st-markets', 'An importing country imposes anti-dumping duties on coil from one origin. Likely effect for traders?', ['Trade flows shift to other origins; landed cost from the targeted origin rises', 'All steel becomes duty-free', 'No effect on landed costs', 'Exports from the importer stop'], 0, 'Trade remedies redirect flows. Traders must check origin-specific duties before quoting landed prices.');
  add('stm3', 'steel', 'st-markets', 'Why are steel hedging opportunities more limited than for gold?', ['Steel has no price', 'Steel is non-standard; available futures/swaps cover specific products and regions and may have limited liquidity, leaving basis risk', 'Hedging steel is illegal', 'Steel prices never move'], 1, 'Derivatives exist for some benchmarks (e.g. certain HRC, rebar, scrap contracts) but a buyer\'s product, region and timing may differ substantially.');

  /* ===================== Stage 4 — physical */
  add('pw1', 'physical', 'p-workflow', 'In a back-to-back physical deal, what should be aligned between purchase and sale contracts?', ['Only the price', 'Quality, quantity tolerance, shipment period, Incoterm/delivery point, documents, inspection, and payment timing', 'Only the vessel name', 'Nothing — they are separate'], 1, 'Mismatches between the two contracts (e.g. different tolerances or inspection points) leave the trader exposed in the gap.');
  add('pw2', 'physical', 'p-workflow', 'Which step should come BEFORE committing to a supplier?', ['Payment of the invoice', 'Counterparty due diligence (KYC, sanctions, track record, financial strength)', 'Discharge at destination', 'Payment reconciliation'], 1, 'Due diligence must precede commitments; after signing, your leverage and options shrink.');
  add('pw3', 'physical', 'p-workflow', 'A buyer offers 4% more per tonne but on 120-day open account; another offers 4% less but pays by confirmed LC at sight. The best choice…', ['Is always the higher price', 'Depends on credit quality, financing cost, risk appetite and limits — the higher price may not compensate for credit and funding risk', 'Is always the LC', 'Is irrelevant'], 1, 'Compare risk-adjusted, financing-adjusted margins. 4% may or may not cover 120 days of funding plus default risk.');
  add('pg1', 'physical', 'p-gold', 'Before buying gold bars from a new supplier, which check is essential?', ['Their social media followers', 'Source of metal (responsible sourcing, AML/KYC), refiner accreditation, assay and bar records', 'Only the price', 'Nothing if paid in cash'], 1, 'Gold is high-value and high AML risk. Verify chain of custody, refiner, assay and counterparty identity; follow responsible-sourcing guidance.');
  add('pg2', 'physical', 'p-gold', 'A seller offers gold at a large discount to the benchmark, requests upfront payment to a third-party account and refuses inspection. This is…', ['A great deal', 'A classic fraud red flag', 'Normal practice', 'Required by Incoterms'], 1, 'Deep discounts + advance payment to third parties + no inspection = typical advance-fee/fake-metal fraud pattern.');
  add('pwh1', 'physical', 'p-wheat', 'Wheat CFR destination is 285/t. The buyer needs it delivered to its mill inland: discharge 6/t, port 4/t, inland truck 12/t, insurance 0.6/t, duty 0. Delivered cost per t (excluding financing)?', ['285', '307.6', '297', '313'], 1, '285 + 6 + 4 + 12 + 0.6 = 307.6 /t. Add each cost layer once.');
  add('pwh2', 'physical', 'p-wheat', 'Who typically performs sampling and analysis for a grain cargo at loading?', ['The vessel\'s crew', 'An independent inspection company (superintendent) as agreed in the contract', 'The buyer\'s bank', 'Nobody'], 1, 'Contracts name the inspection agency, location and whose certificates are final (loading vs discharge).');
  add('ps1', 'physical', 'p-sugar', 'Supplier A: 520 CFR, unreliable. Supplier B: 535 CFR, reliable. Expected extra cost with A from delays/quality ≈ 25/t. Which is cheaper on a risk-adjusted basis?', ['A (520 + 25 = 545)', 'B (535)', 'They are equal', 'Cannot tell'], 1, 'Risk-adjusted cost of A ≈ 545 > 535. Price alone misleads.');
  add('pst1', 'physical', 'p-steel', 'Rebar arrives with mill certificates that do not match the heat numbers on the bundle tags. What is the risk?', ['None', 'Material traceability fails; construction buyer may reject it; potential quality claim', 'It increases the price', 'It speeds up customs'], 1, 'Traceability between bundle tags and MTCs is essential for structural steel acceptance.');
  add('pst2', 'physical', 'p-steel', 'Import duty for steel depends on…', ['Only the weight', 'Tariff classification (HS code), origin (trade remedies, agreements), customs value and the importing country\'s rules', 'The ship flag', 'The buyer\'s name'], 1, 'Classification and origin drive the applicable rates, including anti-dumping and safeguard measures.');

  /* ===================== Stage 5 — trade finance, docs, incoterms, logistics */
  add('tc1', 'documents', 't-contracts', 'Which document is a document of title when issued in negotiable ("to order") form?', ['Commercial invoice', 'Bill of lading', 'Packing list', 'Certificate of origin'], 1, 'An order B/L controls delivery of the goods; endorsing it transfers the right to take delivery.');
  add('tc2', 'documents', 't-contracts', 'Which documents are commodity-specific rather than standard for most shipments?', ['Commercial invoice', 'Phytosanitary certificate (grain), assay certificate (gold), mill test certificate (steel)', 'Bill of lading', 'Insurance certificate'], 1, 'Invoices, transport documents and insurance are general. Phytosanitary, assay, MTC and polarisation analyses are commodity-specific (and still depend on the contract and importing country).');
  add('tc3', 'documents', 't-contracts', 'Should a trader rely on a generic document checklist as legally sufficient for every shipment?', ['Yes', 'No — requirements depend on the contract, LC, commodity, origin, destination country rules, carrier and bank', 'Only for gold', 'Only for CIF'], 1, 'Generic lists are a starting point. Confirm with the contract, LC terms, the importing authority, customs broker and bank.');
  add('tp1', 'finance', 't-payments', 'Rank from LOWEST to HIGHEST risk for the SELLER.', ['Open account, documentary collection, LC, advance payment', 'Advance payment, confirmed LC, documentary collection, open account', 'LC, open account, advance, collection', 'Collection, advance, open account, LC'], 1, 'Advance payment: seller paid before shipping. Confirmed LC: bank undertakings. Collection: banks control documents but no payment undertaking. Open account: pure credit risk.');
  add('tp2', 'finance', 't-payments', 'What is a key difference between a commercial obligation and a bank\'s LC undertaking?', ['There is none', 'The bank\'s undertaking is independent of the sales contract and depends only on complying documents', 'The bank inspects the goods', 'The bank guarantees quality'], 1, 'Under the independence principle banks deal in documents, not goods. A complying presentation must be honoured even if there is a dispute about the goods (fraud exceptions aside, by applicable law).');
  add('tp3', 'finance', 't-payments', 'A standby letter of credit is usually…', ['The primary means of payment', 'A back-up payable on the beneficiary\'s statement that the applicant defaulted', 'A shipping document', 'Issued by the carrier'], 1, 'SBLCs secure performance or payment obligations and are drawn only on default.');
  add('tl1', 'finance', 't-lc', 'Under UCP 600, how long does a bank have to examine documents?', ['21 days', 'A maximum of five banking days following the day of presentation', 'One hour', '30 days'], 1, 'UCP 600 article 14(b): maximum five banking days following the day of presentation to determine compliance.');
  add('tl2', 'finance', 't-lc', 'If an LC is silent on the presentation period, UCP 600 requires presentation of original transport documents not later than…', ['5 days after shipment', '21 calendar days after the date of shipment (and within the expiry)', '60 days', 'Any time before the goods arrive'], 1, 'Article 14(c): 21 calendar days after shipment, but never later than the LC expiry date.');
  add('tl3', 'finance', 't-lc', 'The LC states "500,000 kg", the invoice states 512,000 kg, and the LC has no "about" or tolerance wording. Under UCP 600, is this acceptable for bulk goods?', ['Yes: a 5% tolerance applies for goods not stated in packing units or individual items, if the amount drawn does not exceed the credit amount', 'No — any difference is a discrepancy', 'Only if the vessel agrees', 'Only for gold'], 0, 'Article 30(b) allows 5% more or less for quantity when not stated in packing units/items and the credit amount is not exceeded. 512,000 is +2.4%.');
  add('tl4', 'finance', 't-lc', 'Does UCP 600 automatically apply to every documentary credit?', ['Yes, by international law', 'No — it applies when the credit expressly indicates it is subject to UCP 600', 'Only to standby credits', 'Only in Europe'], 1, 'UCP 600 are contractual rules incorporated by reference (article 1).');
  add('ti1', 'incoterms', 't-incoterms', 'Under CIF, when does risk pass from seller to buyer?', ['When goods arrive at destination', 'When goods are delivered on board the vessel at the port of shipment', 'When the LC is paid', 'When customs clears the goods'], 1, 'CIF and CFR are "shipment" terms: seller pays carriage (and insurance for CIF) to destination, but risk passes at loading.');
  add('ti2', 'incoterms', 't-incoterms', 'Which rules are ONLY for sea and inland waterway transport?', ['EXW, FCA, CPT, CIP', 'FAS, FOB, CFR, CIF', 'DAP, DPU, DDP', 'All eleven'], 1, 'FAS, FOB, CFR and CIF are for sea/inland waterway. The other seven can be used for any mode.');
  add('ti3', 'incoterms', 't-incoterms', 'Containerised steel is handed to the carrier at an inland depot. Which rule fits better than FOB?', ['FCA', 'FAS', 'EXW always', 'DDP'], 0, 'With containers handed over before loading, FCA (or CPT/CIP) matches the point where the seller loses control. FOB leaves the seller at risk while the box waits at the terminal.');
  add('ti4', 'incoterms', 't-incoterms', 'Under Incoterms 2020 CIP, what is the default minimum insurance cover?', ['Institute Cargo Clauses (C)', 'Institute Cargo Clauses (A) (all risks, subject to exclusions)', 'No insurance', 'Seller insures only to loading'], 1, 'Incoterms 2020 raised CIP default cover to ICC (A); CIF remains ICC (C) by default. Parties may agree otherwise.');
  add('ti5', 'incoterms', 't-incoterms', 'Do Incoterms determine when ownership (title) of the goods transfers?', ['Yes, at the point risk passes', 'No — title transfer is governed by the sales contract and applicable law', 'Only under DDP', 'Only for gold'], 1, 'Incoterms cover delivery, risk, costs and clearance responsibilities, not title or payment.');
  add('ls1', 'logistics', 'l-shipping', 'Laytime allowed is 4 days; loading took 6 days; demurrage is 15,000/day. Demurrage due?', ['15,000', '30,000', '60,000', '90,000'], 1, '(6 − 4) × 15,000 = 30,000, subject to the charter party\'s laytime exceptions.');
  add('ls2', 'logistics', 'l-shipping', 'Which vessel type normally carries 50,000 t of raw sugar loose?', ['Container ship', 'Bulk carrier', 'Tanker', 'Ro-ro'], 1, 'Raw sugar moves mostly in bulk carriers (e.g. Supramax/Panamax). Refined sugar often moves bagged in containers or as breakbulk.');
  add('ls3', 'logistics', 'l-shipping', 'Freight is quoted at 32/t for 25,000 t. Port congestion adds 6 days of waiting at 18,000/day demurrage borne by the charterer. Effective freight per t?', ['32.00', '36.32', '38.00', '33.08'], 1, '6 × 18,000 = 108,000; 108,000 / 25,000 = 4.32/t; 32 + 4.32 = 36.32/t.');
  add('lo1', 'logistics', 'l-operations', 'Why is gold usually shipped by secure air freight rather than by sea?', ['Gold is too heavy for ships', 'Very high value per kg makes speed and security worth more than freight cost; insurers and vaults require secure logistics', 'Incoterms forbid sea transport', 'Airports have no customs'], 1, 'Value density drives logistics. A kilogram of gold is worth tens of thousands of dollars; the freight cost is small relative to value and risk.');
  add('lo2', 'logistics', 'l-operations', 'A cargo arrives wet-damaged. What should the receiver do first?', ['Discard it immediately', 'Note protest, call surveyors, preserve evidence and notify insurers/carrier within time limits', 'Pay the supplier extra', 'Ignore it'], 1, 'Claims depend on prompt notice, independent survey and preserved evidence. Time bars apply.');

  /* ===================== Stage 6 — derivatives */
  add('df1', 'derivatives', 'd-futures', 'A gold futures contract covers 100 troy oz with a 0.10 tick. What is the tick value?', ['USD 1', 'USD 10', 'USD 100', 'USD 0.10'], 1, 'Tick value = 0.10 × 100 = USD 10 (illustrative spec, verify current rulebook).');
  add('df2', 'derivatives', 'd-futures', 'You buy 3 wheat futures (5,000 bu each) at 610 c/bu and sell at 596 c/bu. P&L before fees?', ['−2,100', '−21,000', '+2,100', '−700'], 0, '(5.96 − 6.10) × 5,000 × 3 = −0.14 × 15,000 = −2,100 USD.');
  add('df3', 'derivatives', 'd-futures', 'Initial margin 10,000, maintenance 8,000 per contract. Your equity drops to 7,500 with one contract. Margin call amount (restore to initial)?', ['500', '2,500', '10,000', '0'], 1, 'Most futures margin calls require restoring equity to the initial margin: 10,000 − 7,500 = 2,500.');
  add('df4', 'derivatives', 'd-futures', 'Leverage with futures means…', ['You cannot lose more than the margin', 'A small margin controls a large notional, so losses can exceed the margin deposited', 'Prices are fixed', 'No mark-to-market'], 1, 'Futures losses are not limited to margin; you must meet margin calls.');
  add('dh1', 'derivatives', 'd-hedging', 'A flour mill owns 10,000 t of wheat inventory. To hedge price risk it should…', ['Buy wheat futures', 'Sell wheat futures (short hedge)', 'Buy call options', 'Do nothing'], 1, 'Inventory is a long physical position; selling futures offsets price declines.');
  add('dh2', 'derivatives', 'd-hedging', 'Hedged inventory: spot falls 20, futures fall 15. Per unit result of a 1:1 short hedge?', ['0', '−5', '+5', '−35'], 1, 'Physical −20, futures +15 → net −5. Basis weakened by 5: that is basis risk.');
  add('dh3', 'derivatives', 'd-hedging', 'A hedge can create which NEW risk even when it reduces price risk?', ['None', 'Liquidity risk from margin calls on the futures leg while the physical gain is unrealised', 'Quality risk', 'Freight risk'], 1, 'If prices rise, the short futures leg pays margin daily, while the physical gain only arrives when you sell. Hedgers need liquidity lines.');
  add('dh4', 'derivatives', 'd-hedging', 'Why might a short hedge of Black Sea wheat with a US futures contract be imperfect?', ['It is always perfect', 'Different origin, quality, location and currency drivers mean the two prices do not move one-for-one', 'Futures are cash settled', 'Black Sea wheat has no price'], 1, 'Cross-hedging introduces basis risk; regional supply shocks can move one market without the other.');
  add('do1', 'options', 'd-options', 'A call with strike 2,000 costs 45 when futures are at 2,030. Intrinsic and time value?', ['30 and 15', '45 and 0', '0 and 45', '15 and 30'], 0, 'Intrinsic = 2,030 − 2,000 = 30. Time value = 45 − 30 = 15.');
  add('do2', 'options', 'd-options', 'All else equal, what happens to an option\'s value as expiry approaches?', ['Time value increases', 'Time value decays (theta), faster near expiry for at-the-money options', 'Intrinsic value disappears', 'Nothing'], 1, 'Theta erodes time value, accelerating close to expiry for ATM options.');
  add('do3', 'options', 'd-options', 'An option has delta 0.40. Futures rise by 10. Approximate option price change?', ['+10', '+4', '+0.4', '−4'], 1, 'Δoption ≈ delta × ΔF = 0.40 × 10 = 4 (first-order; gamma changes delta as price moves).');
  add('do4', 'options', 'd-options', 'Implied volatility rises from 18% to 24% with no price change. Long option holders…', ['Lose', 'Gain, by roughly vega × 6', 'Are unaffected', 'Must exercise'], 1, 'Vega measures sensitivity to IV; long options are long vega.');
  add('do5', 'options', 'd-options', 'What is the maximum loss for a buyer of a put option?', ['Unlimited', 'The premium paid (plus fees)', 'The strike price', 'Zero'], 1, 'Option buyers can lose at most the premium. Option sellers carry larger risk.');
  add('dsp1', 'spreads', 'd-spreads', 'Gold spot 2,000; financing 5%/yr; lease 1%/yr; storage ignored. Approximate 6-month fair forward?', ['2,000', '2,040', '2,100', '1,960'], 1, '2,000 × (1 + (5% − 1%) × 0.5) = 2,040.');
  add('dsp2', 'spreads', 'd-spreads', 'Why is a positive price gap between two ports not automatically an arbitrage?', ['Because arbitrage is illegal', 'Freight, insurance, duties, financing, quality differences, timing, currency and execution risk may consume or exceed the gap', 'Because exchanges forbid it', 'Because ships are slow'], 1, 'Always compute delivered cost and risks before calling it arbitrage.');
  add('dsp3', 'spreads', 'd-spreads', 'A full-carry contango in grain means the deferred futures premium roughly equals…', ['Freight', 'Storage + financing + insurance costs', 'Import duty', 'Zero'], 1, 'At full carry, holding grain and selling deferred futures just covers carrying costs; spreads wider than full carry are rare because of arbitrage via storage.');

  /* ===================== Stage 7 — analysis & quant */
  add('af1', 'analysis', 'a-fundamental', 'Which data set is the core of fundamental analysis for a crop?', ['Moving averages', 'Supply-and-demand balance: stocks, production, trade, consumption', 'RSI', 'Candlestick colours'], 1, 'Fundamental analysis models physical availability versus use.');
  add('af2', 'analysis', 'a-fundamental', 'Production estimates rise 3% but the market had expected +5%. A likely reaction?', ['Prices fall', 'Prices may rise because the outcome is bullish relative to expectations', 'No reaction ever', 'Volume goes to zero'], 1, 'Markets price expectations; surprises versus consensus drive the reaction.');
  add('at1', 'analysis', 'a-technical', 'RSI reading of 78 means…', ['A guaranteed reversal', 'Recent gains have dominated losses (often called "overbought"); it describes momentum, not certainty', 'Volume is high', 'Price is below its average'], 1, 'Indicators describe past price behaviour. Strong trends can keep RSI high for long periods.');
  add('at2', 'analysis', 'a-technical', 'Price breaks above resistance then falls back below within two sessions. This is called…', ['A confirmed breakout', 'A false breakout', 'Backwardation', 'A margin call'], 1, 'False breakouts trap late buyers; risk management (stops, sizing) matters more than the signal itself.');
  add('at3', 'analysis', 'a-technical', 'Entry 100, stop 96, target 112. Risk-to-reward ratio?', ['1:3', '3:1', '1:4', '1:2'], 0, 'Risk 4, reward 12 → 1:3. A good ratio does not imply a high probability of success.');
  add('aq1', 'quant', 'a-quant', 'Daily volatility is 1.5%. Approximate annualised volatility (252 trading days)?', ['1.5%', '23.8%', '378%', '15%'], 1, '1.5% × √252 ≈ 1.5% × 15.87 = 23.8% (assuming independent returns).');
  add('aq2', 'quant', 'a-quant', 'A correlation of 0.85 between two price series means…', ['One causes the other', 'They have tended to move together linearly over the sample; it may change in the future', 'They are identical', 'Hedging is perfect'], 1, 'Correlation is descriptive and unstable, especially in crises.');
  add('aq3', 'quant', 'a-quant', 'Why use log returns instead of simple returns in volatility models?', ['They are always larger', 'They add up across periods and fit the lognormal price assumption', 'They remove risk', 'Exchanges require them'], 1, 'Log returns are time-additive: ln(P2/P0) = ln(P1/P0) + ln(P2/P1).');
  add('ar1', 'quant', 'a-risk-models', 'A 1-day 95% VaR of 50,000 means…', ['Maximum possible loss is 50,000', 'On about 5% of days, losses are expected to exceed 50,000 if the model holds', 'Losses never exceed 50,000', 'Average loss is 50,000'], 1, 'VaR is a threshold, not a worst case; it is silent about the size of losses beyond it — that is what Expected Shortfall measures.');
  add('ar2', 'quant', 'a-risk-models', 'Main weakness of parametric (normal) VaR for commodities?', ['It is too slow', 'Commodity returns have fat tails, jumps and volatility clustering that the normal distribution understates', 'It cannot be computed', 'It uses no data'], 1, 'Supply shocks create jumps. Complement VaR with stress tests and ES.');
  add('ar3', 'quant', 'a-risk-models', 'Two positions each with 20% volatility and correlation 1.0. Diversification benefit?', ['Large', 'None — portfolio volatility equals the weighted average', 'Volatility halves', 'Volatility doubles'], 1, 'Diversification needs correlation below 1. At ρ=1, risks simply add.');

  /* ===================== Stage 8 — risk & negotiation */
  add('rf1', 'risk', 'r-framework', 'A risk register entry should include…', ['Only the risk name', 'Probability, impact, mitigation, residual exposure, owner and contingency plan', 'Only the trader\'s opinion', 'Only financial risks'], 1, 'A usable register makes risks actionable: who owns them, what is done, what remains and what happens if it occurs.');
  add('rf2', 'risk', 'r-framework', 'Your largest buyer accounts for 65% of receivables. Which risk is elevated?', ['Freight', 'Concentration and credit risk', 'Basis risk', 'Despatch'], 1, 'Concentration magnifies credit risk: one default could threaten liquidity. Use counterparty limits and credit insurance.');
  add('rl1', 'risk', 'r-limits', 'Equity 2,000,000; risk per trade 1%; stop distance 30 per contract unit; contract 100 units. Max contracts?', ['6', '66', '0', '20'], 0, 'Risk budget 20,000 ÷ (30 × 100) = 6.67 → 6 contracts (round down).');
  add('rl2', 'risk', 'r-limits', 'Why combine several shocks in a stress test rather than one at a time?', ['It is faster', 'In crises, shocks cluster (price fall, delays, payment extensions) and losses compound; liquidity needs peak at the same time', 'Regulators forbid single tests', 'It reduces losses'], 1, 'Correlated stresses reveal liquidity and solvency gaps that single-factor tests miss.');
  add('rl3', 'risk', 'r-limits', 'A stop-loss order at 1,950 on a long gold position…', ['Guarantees exit at exactly 1,950', 'Triggers an exit when price trades at or through 1,950; the fill can be worse in a gap', 'Prevents all losses', 'Increases margin'], 1, 'Stops limit losses in normal markets but gaps and illiquidity cause slippage.');
  add('nn1', 'negotiation', 'n-negotiation', 'What is BATNA?', ['A shipping clause', 'Best Alternative To a Negotiated Agreement — your fallback if this deal fails', 'A bank guarantee', 'A futures month'], 1, 'Knowing your BATNA (and estimating theirs) sets your walk-away point.');
  add('nn2', 'negotiation', 'n-negotiation', 'A seller refuses to lower price. Which is a sound trade-off to request?', ['Nothing', 'Better payment terms, wider shipment window, inspection at discharge, or quantity tolerance in your option', 'Ask for a gift', 'Threaten legal action'], 1, 'Value in deals sits in many terms. Trading low-cost concessions for high-value ones creates agreement space.');
  add('nn3', 'negotiation', 'n-negotiation', 'Why specify dispute resolution (e.g. arbitration forum and rules) in a commodity contract?', ['It is decorative', 'It defines how and where disputes are resolved, reducing cost and uncertainty when quality or delivery claims arise', 'It replaces insurance', 'It sets the price'], 1, 'Trade associations and arbitration clauses give predictable procedures for technical commodity disputes.');

  window.CTA.QUESTIONS = Q;
})();
